mapper.sql:
from (select ,
             case when c.status in ('CLOSED', 'CANCELLED') then null
                  when cast(#{q.today} as date) > c.close_due then 'CLOSE_OVERDUE'
                  when c.status = 'OPEN' and cast(#{q.today} as date) > c.contain_due then 'CONTAIN_OVERDUE'
                  else 'ON_TIME' end as due_state
      ) c

    and (c.capa_no ilike #{q.keywordLike} escape '\' or c.title ilike #{q.keywordLike} escape '\'
        or c.cust_cd ilike #{q.keywordLike} escape '\' or c.item_cd ilike #{q.keywordLike} escape '\')
    and c.status = #{q.status}
    and c.source = #{q.source}
    and c.due_state = #{q.dueState}
    and c.status not in ('CLOSED', 'CANCELLED')

mapper.update:
update qms_capa set status = #{to}, contained_at = case when #{to} = 'CONTAINED' then now() else contained_at end,
                    row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where capa_id = #{id} and status = #{from} and row_ver = #{rowVer}

update qms_cust_csr set csr_no = #{f.csrNo}, csr_rev = #{f.csrRev}, title = #{f.title}, effective_from = #{f.effectiveFrom},
                        overrides = #{f.overridesJson}::jsonb, use_yn = #{f.useYn}, remark = #{f.remark},
                        notify_req = coalesce(cast(#{f.notifyReqJson} as jsonb), notify_req),
                        row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where csr_id = #{id} and row_ver = #{f.rowVer}
